// AIProcurementServiceServer is the server API for AIProcurementService service.
// All implementations must embed UnimplementedAIProcurementServiceServer
// for forward compatibility.
type AIProcurementServiceServer interface {
	// 買家：需求輸入
	SubmitTurn(context.Context, *TurnRequest) (*TurnResult, error)
	SubmitTurnStream(*TurnRequest, grpc.ServerStreamingServer[StreamEvent]) error
	GetSnapshot(context.Context, *GetSnapshotRequest) (*SnapshotResponse, error)
	// 買家：候選搜尋（async-poll，兩支對稱，不合併）
	StartCandidateSearch(context.Context, *StartCandidateSearchRequest) (*StartCandidateSearchResponse, error)
	GetCandidateSearch(context.Context, *GetCandidateSearchRequest) (*CandidateSetResponse, error)
	ToggleSelection(context.Context, *ToggleSelectionRequest) (*ToggleSelectionResponse, error)
	// 買家：引導式問答
	SubmitAnswer(context.Context, *SubmitAnswerRequest) (*TurnResult, error)
	Rewind(context.Context, *RewindRequest) (*TurnResult, error)
	// 買家：RFQ 報價預覽（issue #2403 Slice 2）
	PreviewRfqPrice(context.Context, *RfqPricePreviewRequest) (*RfqPricePreviewResponse, error)
	// 買家：RFQ 報價確認（對某次 price preview 產生不可變確認快照，issue #2403 Slice 3）
	ConfirmRfqSnapshot(context.Context, *RfqConfirmationRequest) (*RfqConfirmationResponse, error)
	// 買家：RFQ 發布預覽（產生不可變的 publication approval，issue #2450 Slice 1）
	// ⛔ 只建立 approval，不建立 publication／invite／outbox／projection，也不發任何對外通知。
	PreviewRfqPublication(context.Context, *RfqPublicationPreviewRequest) (*RfqPublicationPreviewResponse, error)
	// 買家：RFQ 發布執行（對 publication approval 做 CAS 執行，issue #2450 Slice 2a）
	// ⛔ state = PUBLISHED 只代表 server transaction 完成，不代表已投遞或已被賣家看到
	// （Scope 9）——本 slice 不建 invite／outbox／projection，也不發任何對外通知。
	ExecuteRfqPublication(context.Context, *RfqPublicationExecuteRequest) (*RfqPublicationExecuteResponse, error)
	// 站外賣家：依 invite id 讀取 RFQ 摘要（Vendor Portal E1 Task 5b）
	GetRfqPublicationInviteSellerView(context.Context, *GetRfqPublicationInviteSellerViewRequest) (*RfqPublicationInviteSellerViewResponse, error)
	// 買家：對話管理
	ListConversations(context.Context, *ListConversationsRequest) (*ListConversationsResponse, error)
	GetConversationMessages(context.Context, *GetConversationMessagesRequest) (*ConversationMessagesResponse, error)
	GetRuntimeSnapshot(context.Context, *GetRuntimeSnapshotRequest) (*RuntimeSnapshotResponse, error)
	// 平台賣家：回價（#2538）。EXTERNAL 半邊的 wire 形狀同樣凍在這裡（invite_id）。
	// ⚠️ 站外業者走的是下方的 VendorPortal 變體（ActorNone），不是這三支。
	ListSellerPublications(context.Context, *ListSellerPublicationsRequest) (*ListSellerPublicationsResponse, error)
	GetSellerPublication(context.Context, *GetSellerPublicationRequest) (*SellerPublicationDetailResponse, error)
	UpsertSellerResponseDraft(context.Context, *UpsertSellerResponseDraftRequest) (*SellerResponseDraftResponse, error)
	GetVendorPortalResponseDraft(context.Context, *GetVendorPortalResponseDraftRequest) (*SellerResponseDraftResponse, error)
	UpsertVendorPortalResponseDraft(context.Context, *UpsertVendorPortalResponseDraftRequest) (*SellerResponseDraftResponse, error)
	// 站外業者的三支正式寫入（要求 assurance = GOOGLE_VERIFIED，見上方 message 註解）。
	SubmitVendorPortalResponse(context.Context, *SubmitVendorPortalResponseRequest) (*SellerResponseVersionResponse, error)
	WithdrawVendorPortalResponse(context.Context, *WithdrawVendorPortalResponseRequest) (*SellerResponseClosureResponse, error)
	DeclineVendorPortalRfqPublication(context.Context, *DeclineVendorPortalRfqPublicationRequest) (*SellerResponseClosureResponse, error)
	SubmitSellerResponse(context.Context, *SubmitSellerResponseRequest) (*SellerResponseVersionResponse, error)
	WithdrawSellerResponse(context.Context, *WithdrawSellerResponseRequest) (*SellerResponseClosureResponse, error)
	DeclineRfqPublication(context.Context, *DeclineRfqPublicationRequest) (*SellerResponseClosureResponse, error)
	// 買家：比較、shortlist 與接受 exact version（#2538）
	ListSellerResponses(context.Context, *ListSellerResponsesRequest) (*ListSellerResponsesResponse, error)
	PutShortlistEntry(context.Context, *ShortlistEntryRequest) (*ShortlistEntryResponse, error)
	DeleteShortlistEntry(context.Context, *ShortlistEntryRequest) (*ShortlistEntryResponse, error)
	AcceptSellerQuote(context.Context, *BuyerQuoteAcceptanceRequest) (*BuyerQuoteAcceptanceResponse, error)
	RenameConversation(context.Context, *RenameConversationRequest) (*emptypb.Empty, error)
	DeleteConversation(context.Context, *DeleteConversationRequest) (*emptypb.Empty, error)
	// 買家：Run ledger 即時訂閱／replay（Task 11，doc57 §2.5 replay 演算法落地）
	WatchRunEvents(*WatchRunEventsRequest, grpc.ServerStreamingServer[RunEvent]) error
	// 買家：Run 取消／恢復（Task 14，doc57 §5.4／§5.5）
	CancelRun(context.Context, *CancelRunRequest) (*CancelRunResponse, error)
	ResumeRun(context.Context, *ResumeRunRequest) (*ResumeRunResponse, error)
	mustEmbedUnimplementedAIProcurementServiceServer()
}

